preConditionHook:
// Signal bar captured on the fill bar, where BarsSinceEntry() is 0.
if (el_eq((double)ctx.BarsSinceEntry(), 0.0)) {
    sigLow = low[1];
    sigHigh = high[1];
}
// A small signal bar invites an outside-bar stop run, so it gets the wider
// offset; every other bar gets the base one. Written as if/else rather than a
// ternary because EasyLanguage has no ternary.
if (el_le(sigHigh - sigLow, smallBarRange)) {
    stopOffsetUsed = widerStopOffset;
} else {
    stopOffsetUsed = baseStopOffset;
}
